import { Box } from '@mui/material'
import {
    MDXEditor, codeBlockPlugin, codeMirrorPlugin, diffSourcePlugin,
    headingsPlugin, imagePlugin, linkDialogPlugin, linkPlugin, listsPlugin, markdownShortcutPlugin, quotePlugin,
    tablePlugin, thematicBreakPlugin, toolbarPlugin,
    type MDXEditorMethods, type ViewMode,
} from '@mdxeditor/editor'
import '@mdxeditor/editor/style.css'
import {
    forwardRef, useCallback, useEffect, useImperativeHandle, useMemo, useRef,
    type FocusEvent, type ReactNode,
} from 'react'
import type { ActionPlaceholder } from '../../data/action_placeholders'
import { dialogService } from '../../services/dialog_service'
import { useAppTheme } from '../../theme/use_app_theme'
import { markdownDocumentHistoryPlugin } from './markdown_document_history_realm_plugin'
import type { MarkdownDocumentHistoryStore } from './markdown_document_history_store'
import { MarkdownFormatToolbarControls } from './markdown_format_toolbar_controls'
import { plainMarkdownPlugin } from './plain_markdown_realm_plugin'
import { markdownPlaceholderPlugin } from './markdown_placeholder_realm_plugin'
import { registerMarkdownEditorFlush } from './markdown_editor_flush'
import { markdownPastePlugin } from './markdown_paste_realm_plugin'
import type {
    ActiveMarkdownDocumentChangedDetail,
    MarkdownBindingKind,
    MarkdownDataSource,
    MarkdownDocumentTarget,
} from './markdown_data_source'
import { buildMarkdownContentSx } from './markdown_style_sx'

const DEFAULT_CODE_LANGUAGE = ''
const CODE_BLOCK_LANGUAGES = { '': 'Plain text', js: 'JavaScript', ts: 'TypeScript', tsx: 'TSX', bash: 'Shell' }
const EMPTY_PLACEHOLDERS: readonly ActionPlaceholder[] = []

export interface MarkdownEditorHandle {
    flush(): boolean
    getMarkdown(): string
    setMarkdown(markdown: string): void
}

interface MarkdownEditorPresentationProps {
    diffMarkdown?: string
    flushOnBlur?: boolean
    /** Omit format toolbar entirely. */
    hideToolbar?: boolean
    overlayContainer?: HTMLElement | null
    placeholders?: readonly ActionPlaceholder[]
    readOnly?: boolean
    stickyToolbar?: boolean
    toolbarContents?: () => ReactNode
    viewMode?: ViewMode
}

interface MarkdownEditorDataSourceProps extends MarkdownEditorPresentationProps {
    binding: MarkdownBindingKind
    dataSource: MarkdownDataSource
    historyStore: MarkdownDocumentHistoryStore
    markdown?: never
    onChange?: never
    onDirtyChange?: never
    onLiveChange?: never
}

interface MarkdownEditorLocalProps extends MarkdownEditorPresentationProps {
    binding?: never
    dataSource?: never
    historyStore?: never
    markdown: string
    onChange: (markdown: string) => void
    onDirtyChange?: (dirty: boolean) => void
    onLiveChange?: (markdown: string) => void
}

type MarkdownEditorProps = MarkdownEditorDataSourceProps | MarkdownEditorLocalProps

interface MarkdownDocumentSnapshot {
    target: MarkdownDocumentTarget | null
    markdown: string
}

interface MarkdownProcessingError {
    error: string
}

function initialDocument(props: MarkdownEditorProps): MarkdownDocumentSnapshot {
    if (!props.dataSource) return { target: null, markdown: props.markdown }

    const target = props.dataSource.getActiveTarget(props.binding)
    return { target, markdown: target ? props.dataSource.getMarkdown(target) : '' }
}

/** Reusable MDXEditor surface with local-buffer and persisted data-source modes. */
export const MarkdownEditor = forwardRef<MarkdownEditorHandle, MarkdownEditorProps>(function MarkdownEditor(props, ref) {
    const {
        flushOnBlur = false,
        diffMarkdown,
        hideToolbar = false,
        overlayContainer,
        placeholders = EMPTY_PLACEHOLDERS,
        readOnly = false,
        stickyToolbar = false,
        toolbarContents: customToolbarContents,
        viewMode,
    } = props
    const dataSource = props.dataSource
    const binding = props.binding
    const historyStore = props.historyStore
    const initialDocumentRef = useRef<MarkdownDocumentSnapshot | null>(null)
    if (!initialDocumentRef.current) initialDocumentRef.current = initialDocument(props)
    const initialDocumentSnapshot = initialDocumentRef.current
    const { markdownStyleConfig, mode } = useAppTheme()
    const editorRef = useRef<MDXEditorMethods>(null)
    const activeTargetRef = useRef(initialDocumentSnapshot.target)
    const latestMarkdownRef = useRef(initialDocumentSnapshot.markdown)
    const lastEmittedMarkdownRef = useRef(initialDocumentSnapshot.markdown)
    const dirtyBaselineEstablishedRef = useRef(false)
    const missingEditorReportedRef = useRef(false)
    const replacingMarkdownRef = useRef(false)
    const onChangeRef = useRef(props.onChange)
    const onDirtyChangeRef = useRef(props.onDirtyChange)
    const onLiveChangeRef = useRef(props.onLiveChange)
    const applyPendingDocumentChangeRef = useRef<() => void>(() => undefined)
    onChangeRef.current = props.onChange
    onDirtyChangeRef.current = props.onDirtyChange
    onLiveChangeRef.current = props.onLiveChange

    const setDirty = useCallback((dirty: boolean) => {
        onDirtyChangeRef.current?.(dirty)
    }, [])

    const flush = useCallback(() => {
        if (latestMarkdownRef.current === lastEmittedMarkdownRef.current) return true

        const activeTarget = activeTargetRef.current
        if (dataSource && binding) {
            if (!activeTarget) return true
            const committed = dataSource.commit(binding, activeTarget, latestMarkdownRef.current)
            if (!committed) return false
        } else {
            onChangeRef.current?.(latestMarkdownRef.current)
        }
        lastEmittedMarkdownRef.current = latestMarkdownRef.current
        setDirty(false)
        queueMicrotask(() => applyPendingDocumentChangeRef.current())

        return true
    }, [binding, dataSource, setDirty])

    const prepareDocumentSwitch = useCallback((detail: ActiveMarkdownDocumentChangedDetail, nextMarkdown: string) => {
        if (detail.discard) lastEmittedMarkdownRef.current = latestMarkdownRef.current
        if (!flush()) return null

        const currentMarkdown = latestMarkdownRef.current
        activeTargetRef.current = detail.target
        latestMarkdownRef.current = nextMarkdown
        lastEmittedMarkdownRef.current = nextMarkdown
        setDirty(false)

        return currentMarkdown
    }, [flush, setDirty])

    const completeDocumentSwitch = useCallback((normalizedMarkdown: string) => {
        latestMarkdownRef.current = normalizedMarkdown
        lastEmittedMarkdownRef.current = normalizedMarkdown
        setDirty(false)
    }, [setDirty])

    const getMarkdown = useCallback(() => editorRef.current?.getMarkdown() ?? latestMarkdownRef.current, [])
    const getTarget = useCallback(() => activeTargetRef.current, [])

    const replaceMarkdown = useCallback((markdown: string) => {
        replacingMarkdownRef.current = true
        editorRef.current?.setMarkdown(markdown)
        replacingMarkdownRef.current = false
    }, [])

    const setPendingDocumentChangeRetry = useCallback((retry: () => void) => {
        applyPendingDocumentChangeRef.current = retry
    }, [])

    const historyPluginConfig = useMemo(() => historyStore && binding && dataSource
        ? {
            binding,
            completeDocumentSwitch,
            dataSource,
            getTarget,
            getMarkdown,
            historyStore,
            prepareDocumentSwitch,
            replaceMarkdown,
            setPendingDocumentChangeRetry,
        }
        : null, [
        binding,
        completeDocumentSwitch,
        dataSource,
        getTarget,
        getMarkdown,
        historyStore,
        prepareDocumentSwitch,
        replaceMarkdown,
        setPendingDocumentChangeRetry,
    ])

    useEffect(() => {
        if (!editorRef.current) {
            if (!missingEditorReportedRef.current) {
                missingEditorReportedRef.current = true
                dialogService.error(new Error('Cannot baseline markdown before editor is mounted'), {fallbackMessage: 'Markdown editor could not be initialized'})
            }
            return
        }

        const normalizedMarkdown = editorRef.current.getMarkdown()
        latestMarkdownRef.current = normalizedMarkdown
        lastEmittedMarkdownRef.current = normalizedMarkdown
        dirtyBaselineEstablishedRef.current = true
    }, [])

    useEffect(() => {
        const unregister = registerMarkdownEditorFlush(flush)

        return () => {
            unregister()
            flush()
        }
    }, [flush])

    useImperativeHandle(ref, () => ({
        flush,
        getMarkdown: () => latestMarkdownRef.current,
        setMarkdown: (markdown: string) => {
            replaceMarkdown(markdown)
            latestMarkdownRef.current = markdown
            lastEmittedMarkdownRef.current = markdown
            setDirty(false)
        },
    }), [flush, replaceMarkdown, setDirty])

    const handleEditorChange = useCallback((markdown: string) => {
        if (replacingMarkdownRef.current || latestMarkdownRef.current === markdown) return

        latestMarkdownRef.current = markdown
        if (!dirtyBaselineEstablishedRef.current) return
        setDirty(markdown !== lastEmittedMarkdownRef.current)
        onLiveChangeRef.current?.(markdown)
        const activeTarget = activeTargetRef.current
        if (dataSource && binding && activeTarget) dataSource.edit(binding, activeTarget, markdown)
    }, [binding, dataSource, setDirty])

    const handleEditorError = useCallback(({ error }: MarkdownProcessingError) => {
        dialogService.error(new Error(error), { fallbackMessage: 'Markdown could not be parsed' })
    }, [])

    const handleBlur = (event: FocusEvent<HTMLDivElement>) => {
        if (!flushOnBlur || event.currentTarget.contains(event.relatedTarget)) return
        flush()
    }

    const insertMarkdown = useCallback((markdown: string) => {
        editorRef.current?.insertMarkdown(markdown)
    }, [])

    const defaultToolbarContents = useCallback(
        () => <MarkdownFormatToolbarControls overlayContainer={overlayContainer} placeholders={placeholders} />,
        [overlayContainer, placeholders],
    )
    const toolbarContents = customToolbarContents ?? defaultToolbarContents
    const markdownContentSx = buildMarkdownContentSx(markdownStyleConfig)
    const stickySx = stickyToolbar
        ? { '& .mdxeditor-toolbar': { position: 'sticky', top: 0, zIndex: 1 } }
        : undefined
    const editorSx = { ...markdownContentSx, ...stickySx }
    const historyPlugin = historyPluginConfig ? markdownDocumentHistoryPlugin(historyPluginConfig) : null
    const plugins = [
        headingsPlugin(),
        listsPlugin(),
        quotePlugin(),
        thematicBreakPlugin(),
        linkPlugin(),
        linkDialogPlugin(),
        imagePlugin(),
        tablePlugin(),
        codeBlockPlugin({ defaultCodeBlockLanguage: DEFAULT_CODE_LANGUAGE }),
        codeMirrorPlugin({ codeBlockLanguages: CODE_BLOCK_LANGUAGES }),
        markdownShortcutPlugin(),
        plainMarkdownPlugin(),
        ...(viewMode ? [diffSourcePlugin({ diffMarkdown: diffMarkdown ?? '', viewMode })] : []),
        ...(hideToolbar ? [] : [toolbarPlugin({ toolbarContents })]),
        markdownPlaceholderPlugin({ overlayContainer, placeholders }),
        markdownPastePlugin({ insertMarkdown }),
        ...(historyPlugin ? [historyPlugin] : []),
    ]

    return (
        <Box data-sticky-toolbar={stickyToolbar} onBlur={handleBlur} sx={editorSx}>
            <MDXEditor
                className={mode === 'dark' ? 'dark-theme' : 'light-theme'}
                contentEditableClassName="mdxeditor-content"
                markdown={initialDocumentSnapshot.markdown}
                onChange={handleEditorChange}
                onError={handleEditorError}
                overlayContainer={overlayContainer}
                plugins={plugins}
                readOnly={readOnly}
                ref={editorRef}
                suppressHtmlProcessing
                suppressSharedHistory={!!historyStore}
            />
        </Box>
    )
})

import {
    LexicalTypeaheadMenuPlugin,
    type MenuRenderFn,
    type TriggerFn,
} from '@lexical/react/LexicalTypeaheadMenuPlugin'
import { List, Paper } from '@mui/material'
import { useCellValue } from '@mdxeditor/editor'
import type { TextNode } from 'lexical'
import { createPortal } from 'react-dom'
import { useCallback, useMemo, useState } from 'react'
import type { ActionPlaceholder } from '../../data/action_placeholders'
import { formatActionPlaceholder } from '../../data/action_placeholders'
import { markdownPlaceholderConfig$ } from './markdown_placeholder_config_cell'
import { MarkdownPlaceholderOption } from './markdown_placeholder_option'
import { MarkdownPlaceholderOptionItem } from './markdown_placeholder_option_item'
import { matchPlaceholderTrigger } from './markdown_placeholder_trigger'

function placeholderMatchesQuery(placeholder: ActionPlaceholder, query: string) {
    return placeholder.name.toLocaleLowerCase().includes(query.toLocaleLowerCase())
}

/** Shows supported placeholders at the caret after the user types `{{`. */
export function MarkdownPlaceholderTypeaheadPlugin() {
    const { overlayContainer, placeholders } = useCellValue(markdownPlaceholderConfig$)
    const [query, setQuery] = useState('')
    const options = useMemo(
        () => placeholders
            .filter((placeholder) => placeholderMatchesQuery(placeholder, query))
            .map((placeholder) => new MarkdownPlaceholderOption(placeholder)),
        [placeholders, query],
    )

    const triggerFn = useCallback<TriggerFn>((text, editor) => {
        const match = matchPlaceholderTrigger(text, editor)
        if (!match || !placeholders.some((placeholder) => placeholderMatchesQuery(placeholder, match.matchingString))) return null

        return match
    }, [placeholders])

    const handleQueryChange = useCallback((nextQuery: string | null) => {
        setQuery(nextQuery ?? '')
    }, [])

    const handleSelectOption = useCallback((
        option: MarkdownPlaceholderOption,
        textNodeContainingQuery: TextNode | null,
        closeMenu: () => void,
    ) => {
        if (!textNodeContainingQuery) return

        textNodeContainingQuery.setTextContent(formatActionPlaceholder(option.placeholder.name))
        textNodeContainingQuery.selectEnd()
        closeMenu()
    }, [])

    const renderMenu = useCallback<MenuRenderFn<MarkdownPlaceholderOption>>((anchorElementRef, itemProps) => {
        if (!anchorElementRef.current || itemProps.options.length === 0) return null

        return createPortal(
            <Paper
                sx={{
                    border: '1px solid',
                    borderColor: 'divider',
                    borderRadius: '14px',
                    boxShadow: 8,
                    minWidth: 280,
                    overflow: 'hidden',
                }}
            >
                <List aria-label="Available placeholders" dense disablePadding role="listbox">
                    {itemProps.options.map((option, index) => (
                        <MarkdownPlaceholderOptionItem
                            index={index}
                            key={option.key}
                            onHighlight={itemProps.setHighlightedIndex}
                            onSelect={itemProps.selectOptionAndCleanUp}
                            placeholder={option.placeholder}
                            selectionOption={option}
                            selected={itemProps.selectedIndex === index}
                            setRefElement={option.setRefElement}
                        />
                    ))}
                </List>
            </Paper>,
            anchorElementRef.current,
        )
    }, [])

    return (
        <LexicalTypeaheadMenuPlugin<MarkdownPlaceholderOption>
            menuRenderFn={renderMenu}
            onQueryChange={handleQueryChange}
            onSelectOption={handleSelectOption}
            options={options}
            parent={overlayContainer ?? undefined}
            triggerFn={triggerFn}
        />
    )
}

import type { TriggerFn } from '@lexical/react/LexicalTypeaheadMenuPlugin'

const PLACEHOLDER_TRIGGER_PATTERN = /\{\{([^{}\s]*)$/u

export const matchPlaceholderTrigger: TriggerFn = (text) => {
    const match = PLACEHOLDER_TRIGGER_PATTERN.exec(text)
    if (!match) return null

    return {
        leadOffset: match.index,
        matchingString: match[1],
        replaceableString: match[0],
    }
}

import { addComposerChild$, realmPlugin } from '@mdxeditor/editor'
import type { ActionPlaceholder } from '../../data/action_placeholders'
import { markdownPlaceholderConfig$ } from './markdown_placeholder_config_cell'
import { MarkdownPlaceholderTypeaheadPlugin } from './markdown_placeholder_typeahead_plugin'

interface MarkdownPlaceholderPluginParams {
    overlayContainer?: HTMLElement | null
    placeholders: readonly ActionPlaceholder[]
}

/** Connects placeholder configuration and caret typeahead to an MDXEditor realm. */
export const markdownPlaceholderPlugin = realmPlugin<MarkdownPlaceholderPluginParams>({
    init(realm, params) {
        if (!params) throw new Error('Markdown placeholder plugin requires parameters')

        realm.register(markdownPlaceholderConfig$)
        realm.pub(markdownPlaceholderConfig$, params)
        realm.pub(addComposerChild$, MarkdownPlaceholderTypeaheadPlugin)
    },
    update(realm, params) {
        if (!params) throw new Error('Markdown placeholder plugin requires parameters')

        realm.pub(markdownPlaceholderConfig$, params)
    },
})

import { Cell } from '@mdxeditor/editor'
import type { ActionPlaceholder } from '../../data/action_placeholders'

export interface MarkdownPlaceholderConfig {
    overlayContainer?: HTMLElement | null
    placeholders: readonly ActionPlaceholder[]
}

export const markdownPlaceholderConfig$ = Cell<MarkdownPlaceholderConfig>({ placeholders: [] })

import { MenuOption } from '@lexical/react/LexicalTypeaheadMenuPlugin'
import type { ActionPlaceholder } from '../../data/action_placeholders'

/** Lexical typeahead option backed by one supported action placeholder. */
export class MarkdownPlaceholderOption extends MenuOption {
    readonly placeholder: ActionPlaceholder

    constructor(placeholder: ActionPlaceholder) {
        super(placeholder.name)
        this.placeholder = placeholder
    }
}

import { ListItemButton, ListItemText } from '@mui/material'
import type { MouseEvent, RefCallback } from 'react'
import { formatActionPlaceholder, type ActionPlaceholder } from '../../data/action_placeholders'
import type { MarkdownPlaceholderOption } from './markdown_placeholder_option'

interface MarkdownPlaceholderOptionItemProps {
    index: number
    onHighlight: (index: number) => void
    onSelect: (option: MarkdownPlaceholderOption) => void
    placeholder: ActionPlaceholder
    selectionOption: MarkdownPlaceholderOption
    selected: boolean
    setRefElement: RefCallback<HTMLElement>
}

/** One mouse- and keyboard-selectable entry in the placeholder typeahead popup. */
export function MarkdownPlaceholderOptionItem(props: MarkdownPlaceholderOptionItemProps) {
    const { index, onHighlight, onSelect, placeholder, selected, selectionOption, setRefElement } = props

    const handleMouseEnter = () => {
        onHighlight(index)
    }

    const handleMouseDown = (event: MouseEvent<HTMLElement>) => {
        event.preventDefault()
    }

    const handleClick = () => {
        onSelect(selectionOption)
    }

    return (
        <ListItemButton
            aria-selected={selected}
            id={`typeahead-item-${index}`}
            onClick={handleClick}
            onMouseDown={handleMouseDown}
            onMouseEnter={handleMouseEnter}
            ref={setRefElement}
            role="option"
            selected={selected}
            sx={{ alignItems: 'flex-start', gap: 1, py: 0.75 }}
        >
            <ListItemText
                primary={formatActionPlaceholder(placeholder.name)}
                secondary={placeholder.description}
                slotProps={{ primary: { component: 'code' }, secondary: { variant: 'caption' } }}
                sx={{ m: 0 }}
            />
        </ListItemButton>
    )
}

import DataObjectOutlined from '@mui/icons-material/DataObjectOutlined'
import { IconButton, Menu, MenuItem, Tooltip } from '@mui/material'
import { activeEditor$, useCellValue } from '@mdxeditor/editor'
import { CONTROLLED_TEXT_INSERTION_COMMAND } from 'lexical'
import { useState, type MouseEvent } from 'react'
import type { ActionPlaceholder } from '../../data/action_placeholders'
import { formatActionPlaceholder } from '../../data/action_placeholders'
import { dialogService } from '../../services/dialog_service'

interface MarkdownPlaceholderToolbarControlProps {
    overlayContainer?: HTMLElement | null
    placeholders: readonly ActionPlaceholder[]
}

/** Toolbar menu that inserts a supported action placeholder at the active selection. */
export function MarkdownPlaceholderToolbarControl(props: MarkdownPlaceholderToolbarControlProps) {
    const { overlayContainer, placeholders } = props
    const activeEditor = useCellValue(activeEditor$)
    const [anchorElement, setAnchorElement] = useState<HTMLElement | null>(null)

    const handleOpen = (event: MouseEvent<HTMLElement>) => {
        setAnchorElement(event.currentTarget)
    }

    const handleClose = () => {
        setAnchorElement(null)
    }

    const handlePlaceholderClick = (event: MouseEvent<HTMLElement>) => {
        try {
            const placeholderName = event.currentTarget.dataset.placeholderName
            const placeholder = placeholders.find(({ name }) => name === placeholderName)
            if (!placeholder) throw new Error(`Unknown Markdown placeholder: ${placeholderName}`)
            if (!activeEditor) throw new Error('Cannot insert a placeholder without an active Markdown editor')

            activeEditor.dispatchCommand(CONTROLLED_TEXT_INSERTION_COMMAND, formatActionPlaceholder(placeholder.name))
            activeEditor.focus()
            handleClose()
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Markdown placeholder could not be inserted' })
        }
    }

    return (
        <>
            <Tooltip title="Insert placeholder">
                <span>
                    <IconButton
                        aria-controls={anchorElement ? 'markdown-placeholder-menu' : undefined}
                        aria-expanded={!!anchorElement}
                        aria-haspopup="menu"
                        aria-label="Insert placeholder"
                        disabled={!activeEditor}
                        onClick={handleOpen}
                        size="small"
                    >
                        <DataObjectOutlined fontSize="small" />
                    </IconButton>
                </span>
            </Tooltip>
            <Menu
                anchorEl={anchorElement}
                container={overlayContainer ?? undefined}
                id="markdown-placeholder-menu"
                onClose={handleClose}
                open={!!anchorElement}
            >
                {placeholders.map((placeholder) => (
                    <MenuItem
                        data-placeholder-name={placeholder.name}
                        key={placeholder.name}
                        onClick={handlePlaceholderClick}
                        sx={{ alignItems: 'flex-start', display: 'flex', flexDirection: 'column' }}
                    >
                        <code>{formatActionPlaceholder(placeholder.name)}</code>
                        <small>{placeholder.description}</small>
                    </MenuItem>
                ))}
            </Menu>
        </>
    )
}

